"""Persist eight complete parent source-body assessments and bounded controls."""
import hashlib
import json
from pathlib import Path

R = Path(__file__).resolve().parents[2]
P = R / 'dag/reviews/additional_rust_linear_algebra_remaining'
path = Path(str(P) + '_notes.json')
notes = json.loads(path.read_bytes())
pins = {x['path']: x['sha256'] for x in json.loads(Path(str(P) + '_scope.json').read_bytes())['files']}
assessments = {
    'src/change_basis.rs': 'Read all633 lines in two complete ranges. Private BasisIsomorphism retains both matrices and matching basis dimensions; public constructors actually replay both inverse products. Checked arithmetic path propagates scalar refusal; ordinary path explicitly warns of raw Add/Mul semantics. Conjugation computes P*A*P_inv under the stated source-to-target coordinate convention. Certificate alone has shapes/provenance, but the containing isomorphism retains the checked matrices without a public mutator, unlike the mixed RankNullity interface. Provenance is caller metadata, not authenticated theorem evidence. Seven embedded boundary examples are substantive; no Rust execution. Independent rational model verifies48 invertible small matrices and3888 transported operators.',
    'src/finite_cochain_map.rs': 'Read all336 lines. Private three-term windows admit matching differential dimensions and d1*d0=0; private cochain maps check both commuting squares. Composition requires equality of the entire intermediate differential presentation, not just dimensions; retraction checks one explicitly documented composite. Ring-valued homotopy checks F-G=dH+Hd in all three degrees with the same endpoints. Under lawful stable scalar operations these are substantive finite equations; quotient interpretation over a general semiring needs a specified congruence, and no norm preservation or equality reflection is claimed. Generic i64 raw operations retain representability premises. Capacity-only tests do not exercise these equations. Independent small F2 models check38 maps,496 compositions and152 fillers; no original execution.',
    'src/linear_observer_presentation.rs': 'Read all221 lines. Exact BigRational entries reject zero denominators and normalize before multiplication. General sensing admits compatible shapes without demanding invisible repairs; strengthening to a quotient report checks every entry of R*d0=0. For Q-vector spaces that condition exactly states constancy on cosets of im(d0). Blindspot records replay the actual supplied repair and report, distinguishing zero from nontrivial hidden repairs. Public DTO forgery is checked by full recomputation. Finite-dimensional rational carriers are not finite sets, as the source explicitly notes; no physical or semantic extraction follows. Three embedded tests cover meaningful visible/hidden/zero/forged/shape cases. Independent81-map-pair control checks2187 shifts; no original execution.',
    'src/row_constraint_implication.rs': 'Read all181 lines. Classifier delegates solving D^T*c=row to exact-field elimination (owner still pending), then separately replays either the complete row combination or a separating vector satisfying D*v=0 and row*v!=0. These are valid rational homogeneous-equation implication certificates for well-formed rationals. Public replay and denominator clearing do not themselves admit raw zero-denominator ratios; well-formed input is a necessary premise. Declared limits explicitly concern matrix allocation and solver operations, not scalar bit lengths, total heap or time. Denominator product is sufficient, not minimal. Sole inline mutation test checks literal Ok/Err and supplies no evidence for the implication owner; no native execution.',
    'src/proof.rs': 'Read all354 lines. IDs reject blank text but retain untrimmed nonempty values; hash wrappers accept arbitrary32-byte caller input. TheoremProvenance is a public descriptive enum, including caller-selectable VerifiedByComputation and unchecked TheoremBoundary, without authentication or theorem checking. Symmetric/positive-definite witnesses have private fields and crate-private unchecked constructors whose checked path is explicitly not wired here; metadata tests inspect those fields, not the mathematical predicate. No public ingress bypass is inferred solely from crate-private constructors, and no original execution occurred.',
    'src/linear_map.rs': 'Read all605 lines in two ranges. Public shape-gated maps retain private matrices and declared basis dimensions. Checked application verifies basis label and coordinate length; composition verifies both intermediate label and dimension, computes checked product and rechecks outer shape. Labels are declared coordinate conventions, not actual basis proofs. Kernel and image methods explicitly return SolverUnavailable, despite the separately implemented canonical solver elsewhere; this interface is incomplete without pretending success. Embedded tests cover mismatch, arithmetic refusal, composition and unavailable methods; stale internal constructor comments do not negate the live public shape gate. No original execution.',
    'src/semiring_lumpability.rs': 'Read all305 lines. Generic ordered product uses only declared semiring operations. Membership validates exhaustive disjoint nonempty blocks, including the unique empty partition. Quotient reads one representative block sum and checks every other representative; MH=HB is exactly the length-one criterion, and associativity/distributivity inductively give M^nH=HB^n. This needs no subtraction or scalar multiplicative commutativity and preserves endpoint-block aggregates, not individual paths. Push-forward computes P*M*P^T for an admitted finite map, with loops/reverse arcs independent. Strong finite mathematical core with scalar-law and resource premises; substantive small tests plus unrelated capacity tests are retained. Independent162 small matrix/partition pairs give100 admissions checked through power5. No original execution.',
    'src/semiring_matrix.rs': 'Read all306 lines. Shape-checked semiring multiplication, repeated-squaring powers and exhaustive Boolean square roots for n<=3 are substantive bounded algorithms. Boolean OR/AND operations are lawful; enumeration visits every2^(n*n) candidate and returns no partial answer on over-cap n. Independent relational composition checks all512 Boolean3x3 candidates. Named MAX_SCALAR_OPERATIONS counts dot-product terms although each term calls mul and add;256x256 multiplication passes with2^24 terms but2^25 scalar method calls. Each power multiplication gets a fresh per-call bound, not a total exponentiation budget. to_rows has no element/row-output quota; a zero-column source can still request many empty rows. Generic scalar law/representability premises persist. Real finite root/power tests and unrelated capacity tests were read, not executed.'
}
for name, assessment in assessments.items():
    notes['files'][name] = {'full_source_read': True, 'assessment': assessment}
notes['files']['src/choice.rs']['assessment'] = notes['files']['src/choice.rs']['assessment'].replace('still pending', 'now fully read and separately assessed')

def ev(name, lo, hi):
    p = 'code/rust/core_linear_algebra/' + name
    return {'path': p, 'sha256': pins[p], 'lines': [lo, hi]}

claims = [
    {'id': 'RLA-C08', 'statement': 'The checked basis-change constructor replays both inverse products and retains its matrices; typed linear-map composition checks both intermediate basis label and dimension. These enforce concrete coordinate relations under lawful exact scalar arithmetic, while provenance remains caller-supplied metadata.', 'evidence': [ev('src/change_basis.rs', 294, 338), ev('src/change_basis.rs', 392, 444), ev('src/linear_map.rs', 174, 260), ev('src/proof.rs', 146, 169)], 'controls': ['RLA-P08'], 'limits': 'No actual basis family, authenticated theorem or public kernel/image implementation is supplied by these wrappers; no original execution.'},
    {'id': 'RLA-C09', 'statement': 'The cochain window, map and homotopy owners check complete finite matrix equations: d1*d0=0, commuting squares and F-G=dH+Hd with shared endpoints. For lawful ring coefficients this makes the usual induced cohomology and homotopy reasoning available under the supplied presentation.', 'evidence': [ev('src/finite_cochain_map.rs', 18, 75), ev('src/finite_cochain_map.rs', 101, 133), ev('src/finite_cochain_map.rs', 136, 218)], 'controls': ['RLA-P12'], 'limits': 'Semiring quotients require an explicit congruence; no semantic extraction, norm preservation or reflection of equality is implied. Independent finite F2 control only.'},
    {'id': 'RLA-C10', 'statement': 'Rational sensing is strengthened to a report on repair cosets exactly by checking R*d0=0. Its supplied blindspot witness is recomputed, and the homogeneous-equation implication wrapper separately replays row-combination or separating-vector evidence.', 'evidence': [ev('src/linear_observer_presentation.rs', 26, 83), ev('src/linear_observer_presentation.rs', 107, 155), ev('src/row_constraint_implication.rs', 52, 148)], 'controls': ['RLA-P10'], 'limits': 'Well-formed exact rationals and available resources are premises; implication solver body remains pending. No memory, policy, physical or general answer-correctness interpretation is derived.'},
    {'id': 'RLA-C11', 'statement': 'The lumpability owner validates an exhaustive partition and the exact intertwining equation MH=HB. Its induction genuinely preserves endpoint-block path aggregates for every length under lawful semiring operations. The separate Boolean square-root routine exhaustively enumerates its admitted n<=3 carrier.', 'evidence': [ev('src/semiring_lumpability.rs', 1, 9), ev('src/semiring_lumpability.rs', 62, 135), ev('src/semiring_matrix.rs', 95, 143)], 'controls': ['RLA-P09'], 'limits': 'Endpoint-block aggregates are not individual paths or arbitrary-distribution preservation. Finite models corroborate the source reasoning; no native execution or universal runtime bound.'}
]
finding = {'id': 'RLA-F03', 'statement': 'The semiring multiplication budget named MAX_SCALAR_OPERATIONS counts one unit per dot-product term although the body calls both mul and add. An admitted256-square multiplication therefore performs2^25 such scalar calls against the named2^24 limit.', 'evidence': [ev('src/semiring_matrix.rs', 7, 28), ev('src/semiring_matrix.rs', 52, 69)], 'controls': ['RLA-P11'], 'limits': 'Exact loop-count model, not a large runtime experiment. The term count is bounded and no elapsed-time guarantee is established or refuted.', 'recommended_action': 'Rename the limit as a dot-product-term bound, or count both scalar calls consistently with the checked BasicMatrix owner and document per-call versus whole-power accounting.'}
for group, items in [('claims', claims), ('findings', [finding])]:
    ids = {x['id'] for x in items}
    notes[group] = [x for x in notes[group] if x['id'] not in ids] + items
receipt = Path(str(P) + '_controls03.json')
result = json.loads(receipt.read_bytes())
assert result['status'] == 'finite_controls_pass'
assert hashlib.sha256(receipt.with_suffix('.py').read_bytes()).hexdigest() == result['helper_sha256']
ids = {x['id'] for x in result['controls']}
notes['controls'] = [x for x in notes['controls'] if x['id'] not in ids]
for item in result['controls']:
    notes['controls'].append({**item, 'receipt': {'path': receipt.relative_to(R).as_posix(), 'sha256': hashlib.sha256(receipt.read_bytes()).hexdigest()}})
path.write_text(json.dumps(notes, indent=2, ensure_ascii=False) + '\n', encoding='utf8')
print('Persisted eight full-body assessments, four claims, one scoped finding and five controls.')
